"""Per-run plan state and the native ``update_plan`` tool for Copilot v2.

The model never supplies item ids (a hallucination vector in v1). Each call
replaces the whole plan; the server assigns positional ids ``"1"``..``"n"``.
Invariant violations are returned as tool text, never raised, so a bad plan
update cannot abort a run.
"""

from __future__ import annotations

from collections.abc import Sequence
from enum import Enum
from typing import Any
from uuid import uuid4

import structlog
from pydantic import BaseModel, Field
from pydantic_ai import Agent, RunContext

from rasa.builder.copilot.pydantic_ai.run_context import CopilotRunContext

structlogger = structlog.get_logger()

PLAN_TOOL_NAME = "update_plan"

PLAN_CLEARED_MESSAGE = "plan cleared"
IN_PROGRESS_CORRECTION = (
    "only one item may be in_progress; statuses recorded as given — "
    "fix on your next update"
)

_PLAN_TOOL_DESCRIPTION = (
    "Replace the current task plan with this complete list. Call before "
    "starting multi-step work, then again whenever any item's status changes. "
    "Each call replaces the whole plan — always send every item with its "
    "current status. Do not include item ids; the server assigns them. "
    "Exactly one item should be in_progress at a time."
)

_STATUS_ICONS = {
    "pending": "⏳",
    "in_progress": "🔄",
    "completed": "✅",
    "cancelled": "❌",
    "failed": "❌",
}


class PlanStatus(str, Enum):
    """Status of one plan item. Values match the v1 todo-list wire strings."""

    PENDING = "pending"
    IN_PROGRESS = "in_progress"
    COMPLETED = "completed"
    CANCELLED = "cancelled"
    FAILED = "failed"


class PlanToolItem(BaseModel):
    """One plan item as supplied by the model. No ``id`` field on purpose."""

    content: str = Field(description="Description of the task.")
    status: PlanStatus = Field(
        default=PlanStatus.PENDING,
        description="Current status of the task.",
    )


class PlanItem(BaseModel):
    """One stored plan item with a server-assigned positional id."""

    id: str
    content: str
    status: PlanStatus


class PlanState:
    """Per-run plan checklist. Each ``replace`` is a full-state snapshot."""

    def __init__(self) -> None:
        self._items: list[PlanItem] = []

    def replace(self, items: Sequence[PlanToolItem]) -> str:
        """Replace the plan with ``items`` and return the model-facing text.

        Args:
            items: The complete new plan. An empty list clears the plan.

        Returns:
            ``"plan cleared"`` when ``items`` is empty; otherwise the formatted
            plan. When more than one item is ``in_progress``, the plan is still
            stored as given and the return value starts with a correction note.
        """
        self._items = _items_with_positional_ids(items)
        structlogger.info(
            "copilot_v2.plan.replaced",
            task_count=len(self._items),
        )
        if not self._items:
            return PLAN_CLEARED_MESSAGE
        formatted = _format_plan(self._items)
        if _in_progress_count(self._items) > 1:
            return f"{IN_PROGRESS_CORRECTION}\n\n{formatted}"
        return formatted

    def snapshot(self) -> dict[str, Any]:
        """Return the wire payload ``{"tasks": [...]}`` the frontend consumes."""
        return {
            "tasks": [item.model_dump(mode="json") for item in self._items],
        }

    def is_empty(self) -> bool:
        """Return whether the plan currently has no items."""
        return not self._items


def persisted_plan_row(snapshot: dict[str, Any]) -> dict[str, Any]:
    """Build the AG-UI message row that rehydrates a turn's final plan.

    Args:
        snapshot: The ``{"tasks": [...]}`` payload from :meth:`PlanState.snapshot`.

    Returns:
        A row with ``role="plan"`` carrying the same ``tasks`` list the live
        ``plan_update`` CUSTOM event streamed.
    """
    return {
        "id": f"plan-{uuid4().hex}",
        "role": "plan",
        "tasks": snapshot["tasks"],
    }


def register_plan_tool(agent: Agent[CopilotRunContext, str]) -> None:
    """Register the native ``update_plan`` tool on the agent.

    The tool writes to ``ctx.deps.plan`` and returns formatted plan text so the
    current checklist stays fresh in the model's context after every update.
    """

    @agent.tool(name=PLAN_TOOL_NAME, description=_PLAN_TOOL_DESCRIPTION)
    async def update_plan(
        ctx: RunContext[CopilotRunContext],
        items: list[PlanToolItem],
    ) -> str:
        """Replace the current plan with ``items`` and return the formatted state."""
        return ctx.deps.plan.replace(items)


def _items_with_positional_ids(items: Sequence[PlanToolItem]) -> list[PlanItem]:
    """Assign ids ``"1"``..``"n"`` in list order."""
    return [
        PlanItem(id=str(index), content=item.content, status=item.status)
        for index, item in enumerate(items, start=1)
    ]


def _in_progress_count(items: Sequence[PlanItem]) -> int:
    """Return how many items are currently ``in_progress``."""
    return sum(item.status == PlanStatus.IN_PROGRESS for item in items)


def _format_plan(items: Sequence[PlanItem]) -> str:
    """Format the plan as text so it stays fresh in the model's context."""
    lines = ["Current plan:"]
    for item in items:
        icon = _STATUS_ICONS.get(item.status.value, "•")
        lines.append(f"  {item.id}. {item.content} [{item.status.value}] {icon}")
    return "\n".join(lines)
